package android.provider;import android.content.Context;import android.net.Uri;public final class DocumentsContract {public static boolean isDocumentUri(Context c,Uri u){return u.toString().contains("/document/");}public static String getDocumentId(Uri u){return u.toString().split("/document/",2)[1].split("[?#]",2)[0];}public static final class Document{public static final String COLUMN_MIME_TYPE="mime_type",COLUMN_SIZE="_size",MIME_TYPE_DIR="vnd.android.document/directory";}}
